class LazyLoadingManager{constructor(){this.imageSelector='img[loading="lazy"]';this.placeholderClass='lazy-placeholder';this.loadedClass='lazy-loaded';this.errorClass='lazy-error';this.init();}init(){if ('loading' in HTMLImageElement.prototype){this.setupNativeLazyLoading();}else{this.setupIntersectionObserver();}}setupNativeLazyLoading(){const images=document.querySelectorAll(this.imageSelector);images.forEach(img=>{this.setupImageErrorHandling(img);this.addPlaceholder(img);});}setupIntersectionObserver(){const options={root:null,rootMargin:'50px',threshold:0.01};const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if (entry.isIntersecting){this.loadImage(entry.target);observer.unobserve(entry.target);}});},options);const images=document.querySelectorAll(this.imageSelector);images.forEach(img=>{this.addPlaceholder(img);observer.observe(img);});}loadImage(img){const src=img.getAttribute('data-src')||img.getAttribute('src');const srcset=img.getAttribute('data-srcset');if (!src)return;const tempImg=new Image();tempImg.onload=()=>{img.src=src;if (srcset){img.srcset=srcset;}img.classList.add(this.loadedClass);img.classList.remove(this.placeholderClass);this.removePlaceholder(img);};tempImg.onerror=()=>{img.classList.add(this.errorClass);this.removePlaceholder(img);};tempImg.src=src;}addPlaceholder(img){if (img.parentElement&&img.parentElement.classList.contains(this.placeholderClass)){return;}const placeholder=document.createElement('div');placeholder.className=`${this.placeholderClass}bg-gray-200 animate-pulse`;placeholder.style.width=img.width||'100%';placeholder.style.height=img.height||'auto';placeholder.style.aspectRatio=img.getAttribute('data-aspect-ratio')||'auto';img.parentElement?.insertBefore(placeholder,img);img.classList.add(this.placeholderClass);}removePlaceholder(img){const placeholder=img.parentElement?.querySelector(`.${this.placeholderClass}`);if (placeholder&&placeholder!==img){placeholder.remove();}}setupImageErrorHandling(img){img.addEventListener('error',()=>{img.classList.add(this.errorClass);this.removePlaceholder(img);console.warn('Failed to load image:',img.src);});img.addEventListener('load',()=>{img.classList.add(this.loadedClass);this.removePlaceholder(img);});}}document.addEventListener('DOMContentLoaded',function (){new LazyLoadingManager();});function reinitializeLazyLoading(){new LazyLoadingManager();}if (typeof module!=='undefined'&&module.exports){module.exports=LazyLoadingManager;}